use std::fs;
use std::path::Path;

/// Declarations for functions generated by macros (invisible to cbindgen).
const MACRO_GENERATED_DECLS: &str = r#"
#ifdef __cplusplus
extern "C" {
#endif

/* --- Block column accessors (macro-generated) --- */
/* Function names use the type alias names: F, I, U.                       */
/* Widths are fixed: F=double (f64), I=int32_t (i32), U=uint32_t (u32).    */

/* Zero-copy read */
enum MolrsStatus molrs_block_get_F(struct MolrsBlockHandle block, uint32_t col_key_id,
                                    const F **out_ptr, uintptr_t *out_len);
enum MolrsStatus molrs_block_get_I(struct MolrsBlockHandle block, uint32_t col_key_id,
                                    const int32_t **out_ptr, uintptr_t *out_len);
enum MolrsStatus molrs_block_get_U(struct MolrsBlockHandle block, uint32_t col_key_id,
                                    const uint32_t **out_ptr, uintptr_t *out_len);

/* Zero-copy write */
enum MolrsStatus molrs_block_get_F_mut(struct MolrsBlockHandle *block, uint32_t col_key_id,
                                        F **out_ptr, uintptr_t *out_len);
enum MolrsStatus molrs_block_get_I_mut(struct MolrsBlockHandle *block, uint32_t col_key_id,
                                        int32_t **out_ptr, uintptr_t *out_len);
enum MolrsStatus molrs_block_get_U_mut(struct MolrsBlockHandle *block, uint32_t col_key_id,
                                        uint32_t **out_ptr, uintptr_t *out_len);

/* Copy path */
enum MolrsStatus molrs_block_copy_F(struct MolrsBlockHandle block, uint32_t col_key_id,
                                     F *out_buf, uintptr_t buf_len);
enum MolrsStatus molrs_block_copy_I(struct MolrsBlockHandle block, uint32_t col_key_id,
                                     int32_t *out_buf, uintptr_t buf_len);
enum MolrsStatus molrs_block_copy_U(struct MolrsBlockHandle block, uint32_t col_key_id,
                                     uint32_t *out_buf, uintptr_t buf_len);

/* Insert (set) columns */
enum MolrsStatus molrs_block_set_F(struct MolrsBlockHandle *block, uint32_t col_key_id,
                                    const F *data, const uintptr_t *shape, uintptr_t ndim);
enum MolrsStatus molrs_block_set_I(struct MolrsBlockHandle *block, uint32_t col_key_id,
                                    const int32_t *data, const uintptr_t *shape, uintptr_t ndim);
enum MolrsStatus molrs_block_set_U(struct MolrsBlockHandle *block, uint32_t col_key_id,
                                    const uint32_t *data, const uintptr_t *shape, uintptr_t ndim);

#ifdef __cplusplus
}  // extern "C"
#endif
"#;

fn main() {
    emit_runtime_rpath();

    // `emit_runtime_rpath` emits `rerun-if-env-changed`, which switches this
    // script off cargo's default "re-run when any file in the package changed"
    // scan. Declare cbindgen's real inputs so the generated header cannot go
    // stale — and so writing `include/molrs.h` (an OUTPUT living inside the
    // package dir) no longer re-triggers the script on every build.
    println!("cargo::rerun-if-changed=src");
    println!("cargo::rerun-if-changed=cbindgen.toml");
    println!("cargo::rerun-if-changed=Cargo.toml");
    println!("cargo::rerun-if-changed=build.rs");

    let crate_dir = std::env::var("CARGO_MANIFEST_DIR").unwrap();
    let header_path = format!("{crate_dir}/include/molrs.h");
    let config = cbindgen::Config::from_file("cbindgen.toml").unwrap_or_default();

    match cbindgen::Builder::new()
        .with_crate(&crate_dir)
        .with_config(config)
        .generate()
    {
        Ok(bindings) => {
            bindings.write_to_file(&header_path);

            // Append macro-generated declarations before the closing #endif
            let content = fs::read_to_string(&header_path).unwrap();
            let closing = "#endif  /* MOLRS_H */";
            if let Some(pos) = content.rfind(closing) {
                let patched = format!("{}{}{}", &content[..pos], MACRO_GENERATED_DECLS, closing);
                fs::write(&header_path, patched).unwrap();
            }
        }
        Err(cbindgen::Error::ParseSyntaxError { .. }) => {
            eprintln!("cargo:warning=cbindgen failed to parse; header not generated");
        }
        Err(e) => {
            // Don't fail the build if header already exists
            if Path::new(&header_path).exists() {
                eprintln!("cargo:warning=cbindgen error: {e:?}; using existing header");
            } else {
                panic!("cbindgen failed: {e:?}");
            }
        }
    }
}

/// Emits the runtime rpath the opt-in dynamic link form needs.
///
/// The zero-argument default links statically, and there this load command is
/// simply unused — inert, not harmful — so it is emitted unconditionally
/// rather than guessed from the command line. Under the dynamic opt-in
/// (`docs/interop.md`) the `libmolrs_ffi` dylib in the shared target dir
/// records a *hashless absolute* `install_name`, so this artifact resolves the
/// shared molrs image by that path alone and needs no rpath entry for it. What
/// does need one is the dynamically linked libstd, which rustc references as
/// `@rpath/libstd-*.dylib`.
///
/// Deliberately duplicated across the four consumer build scripts: sharing it
/// would take a build-dependency crate, and molpack publishes to crates.io, so
/// that means a new published crate. Twenty lines beat a release-train
/// dependency.
fn emit_runtime_rpath() {
    // wasm has no dynamic linking at all, so neither link form applies to it
    // and there is nothing to inject.
    if std::env::var("CARGO_CFG_TARGET_ARCH").as_deref() == Ok("wasm32") {
        return;
    }

    // `-Wl,-rpath` is an ELF / Mach-O concept (the value may be a comma list,
    // e.g. "unix,wasm"). MSVC has no rpath, and the static default needs none
    // anywhere.
    let family = std::env::var("CARGO_CFG_TARGET_FAMILY").unwrap_or_default();
    if !family.split(',').any(|f| f == "unix") {
        return;
    }

    let rustc = std::env::var("RUSTC").unwrap_or_else(|_| "rustc".to_string());
    let target = std::env::var("TARGET").expect("cargo sets TARGET for every build script");
    let fix = format!("rustc --print target-libdir --target {target}");

    // Every failure below is a contract violation, not a missing optional:
    // without libstd's directory the dynamically linked artifact loads with an
    // unresolved `@rpath/libstd-*`. Panic with the reproducing command — never
    // downgrade this path to `cargo::warning`.
    let out = std::process::Command::new(&rustc)
        .args(["--print", "target-libdir", "--target", &target])
        .output()
        .unwrap_or_else(|err| {
            panic!("could not run `{rustc}` ({err}); expected the libstd dir for `{target}`: {fix}")
        });
    if !out.status.success() {
        panic!(
            "`{rustc} --print target-libdir` failed ({}); expected the libstd dir for `{target}`: {fix}",
            out.status
        );
    }
    let libdir = String::from_utf8_lossy(&out.stdout).trim().to_string();
    if libdir.is_empty() {
        panic!(
            "`{rustc} --print target-libdir` printed nothing; expected the libstd dir for `{target}`: {fix}"
        );
    }
    if !std::path::Path::new(&libdir).is_dir() {
        panic!(
            "rustc reported target-libdir `{libdir}`, which is not a directory; expected the libstd dir for `{target}`: {fix}"
        );
    }

    // The libstd rpath the dynamic opt-in needs. Inert under the static
    // default: nothing resolves through `@rpath` there, so the load command
    // goes unused.
    println!("cargo::rustc-link-arg=-Wl,-rpath,{libdir}");
    println!("cargo::rerun-if-env-changed=RUSTC");
    println!("cargo::rerun-if-env-changed=TARGET");
}
